# Binary Search in Rust

Here's a clean implementation of binary search over a sorted slice of `i64`, along with two unit tests.

```rust
/// Performs binary search on a sorted slice of `i64`.
///
/// Returns `Some(index)` if `target` is found, or `None` otherwise.
///
/// # Panics
/// Does not panic; assumes the slice is sorted in ascending order.
pub fn binary_search(haystack: &[i64], target: i64) -> Option<usize> {
    let mut low: usize = 0;
    let mut high: usize = haystack.len();

    while low < high {
        // Avoids overflow compared to `(low + high) / 2`.
        let mid = low + (high - low) / 2;

        match haystack[mid].cmp(&target) {
            std::cmp::Ordering::Less => low = mid + 1,
            std::cmp::Ordering::Greater => high = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }

    None
}

